// DropMetricName returns Labels with "__name__" removed.
func (ls Labels) DropMetricName() Labels {
	for i, l := range ls {
		if l.Name == MetricName {
			if i == 0 { // Make common case fast with no allocations.
				return ls[1:]
			}
			// Use a full slice expression to force append to allocate a new
			// backing array instead of shifting the labels in place, which
			// would corrupt other labels sharing the same array.
			return append(ls[:i:i], ls[i+1:]...)
		}
	}
	return ls
}
